const wh = $('1. Webhook').first();
const headers = wh.json.headers || {};
const body = wh.json.body || {};
const filename = headers['x-original-filename'] || 'audio.mp3';
const ext = (filename.split('.').pop() || 'mp3').toLowerCase();
const uuid = 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
  const r = (Math.random() * 16) | 0;
  return (c === 'x' ? r : (r & 0x3) | 0x8).toString(16);
});
const meeting_id = uuid;

// [multitenant v2] user_id vem do header X-User-Id propagado pelo caller
// (mac-agent, PWA, /api/meetings/[id]/segments). Fallback pro Vitor durante
// rollout (VITOR_FALLBACK_UUID setado no env do n8n).
const user_id = headers['x-user-id'] || $env.VITOR_FALLBACK_UUID || body.user_id;
if (!user_id) {
  throw new Error('X-User-Id ausente e VITOR_FALLBACK_UUID não configurado');
}
const now = new Date();
const year  = String(now.getUTCFullYear());
const month = String(now.getUTCMonth() + 1).padStart(2, '0');
const recorded_at = headers['x-recorded-at'] || now.toISOString();

const transcription = body.transcription || '';
const duration_seconds_local = parseFloat(body.duration_seconds || '0');
const silent_local = (body.silent === 'true' || body.silent === true);

// segments: vem como string JSON (multipart form field). Parse pra array de objetos.
let segments_local = [];
if (body.segments) {
  try {
    segments_local = typeof body.segments === 'string'
      ? JSON.parse(body.segments)
      : body.segments;
    if (!Array.isArray(segments_local)) segments_local = [];
  } catch (e) {
    segments_local = [];
  }
}

return [{
  json: {
    meeting_id,
    user_id,
    year, month,
    source: headers['x-source'] || 'macbook',
    meeting_type: headers['x-meeting-type'] || 'desconhecido',
    original_filename: filename,
    recorded_at,
    audio_size_bytes: parseInt(headers['x-audio-size'] || '0', 10),
    ext,
    audio_path: `/audios/${meeting_id}.${ext}`,
    transcription,
    duration_seconds_local,
    silent_local,
    segments_local,
  },
  binary: wh.binary
}];

// Mantém JSON do step anterior (save-audio response) e restaura binary do step 3
// (HTTP Request consome o binary, mas Whisper precisa dele)
return [{
  json: $json,
  binary: $('3. Prepare Metadata').first().binary
}];

// Usa transcrição + segments já prontos do Mac.
// Formato compatível: { text, duration, language, segments }.
const meta = $('3. Prepare Metadata').first().json;
return [{
  json: {
    text: meta.transcription || '',
    duration: meta.duration_seconds_local || 0,
    language: 'pt',
    segments: meta.segments_local || [],
  }
}];

// Auto-aceita propostas do voice-svc com alta confiança.
// Input: resposta do /identify → { labels: { letter: {pessoa_id, nome, confidence, sample_count, margin} } }
// Quando o nó 7b falha (neverError), input vem vazio — passa adiante com objetos vazios.
const HIGH_CONFIDENCE = 0.80;
const MARGIN_MIN = 0.08;
const SAMPLE_MIN = 2;

const input = $input.first();
const resp = (input && input.json) || {};
const proposed = resp.labels || {};

const speaker_labels = {};
const speaker_pessoas = {};

for (const [letter, prop] of Object.entries(proposed)) {
  if (!prop || !prop.pessoa_id) continue;
  if (prop.confidence >= HIGH_CONFIDENCE
      && (prop.margin || 0) >= MARGIN_MIN
      && (prop.sample_count || 0) >= SAMPLE_MIN) {
    speaker_labels[letter] = prop.nome;
    speaker_pessoas[letter] = prop.pessoa_id;
  }
}

const meta = $('3. Prepare Metadata').first().json;
return [{ json: {
  meeting_id: meta.meeting_id,
  user_id: meta.user_id,
  speaker_labels,
  speaker_pessoas,
  speaker_labels_json: JSON.stringify(speaker_labels),
  speaker_pessoas_json: JSON.stringify(speaker_pessoas),
  n_auto_accepted: Object.keys(speaker_labels).length,
}}];

// Monta texto rotulado a partir dos segments + speaker_labels.
// Quando não há segments OU não há labels, devolve transcrição crua (GPT continua funcionando).
const meta = $('3. Prepare Metadata').first().json;
const pre = $('6. Use Pretranscribed').first().json;
const labels = $('7c. Auto-Accept High Confidence').first().json.speaker_labels || {};
const segments = pre.segments || [];
const transcription = pre.text || '';

if (!segments.length) {
  return [{ json: {
    meeting_id: meta.meeting_id,
    user_id: meta.user_id,
    recorded_at: meta.recorded_at,
    source: meta.source,
    meeting_type: meta.meeting_type,
    labeled_text: transcription,
  }}];
}

// agrupa segments contíguos do mesmo speaker em turnos
const turns = [];
for (const s of segments) {
  const last = turns[turns.length - 1];
  if (last && last.speaker === s.speaker) {
    last.text += s.text;
  } else {
    turns.push({ speaker: s.speaker, text: s.text });
  }
}

const lines = turns.map(t => {
  const name = labels[t.speaker] || `Speaker ${t.speaker}`;
  return `${name}: ${(t.text || '').trim()}`;
});

return [{ json: {
  meeting_id: meta.meeting_id,
  user_id: meta.user_id,
  recorded_at: meta.recorded_at,
  source: meta.source,
  meeting_type: meta.meeting_type,
  labeled_text: lines.join('\n'),
}}];

